import{_ as o,c as n,o as t,ah as a}from"./chunks/framework.oAolcYhj.js";const u=JSON.parse('{"title":"Testdaten für lokale Handbuch-Screenshots","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/qonnectra-demo-data/README.md","filePath":"scripts/qonnectra-demo-data/README.md"}'),i={name:"scripts/qonnectra-demo-data/README.md"};function d(r,e,s,c,l,p){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="testdaten-fur-lokale-handbuch-screenshots" tabindex="-1">Testdaten für lokale Handbuch-Screenshots <a class="header-anchor" href="#testdaten-fur-lokale-handbuch-screenshots" aria-label="Permalink to &quot;Testdaten für lokale Handbuch-Screenshots&quot;">​</a></h1><p><code>testprojekt-export.json</code> ist ein 1:1-Export des echten Projekts <strong>&quot;Testprojekt&quot;</strong> von app.geodock.de (Netzknoten, Trassen, Rohre, Adressen, Kabel, Fasern, Mikrorohre, Gebiete inkl. der dazugehörigen Referenzdaten wie Firmen, Rohr-/Kabeltypen und Kennzeichen). <code>scripts/setup-local-qonnectra.sh</code> spielt diese Datei automatisch in eine frische lokale Instanz ein.</p><p>Bewusst <strong>nicht</strong> enthalten: Container/ContainerType, FiberSplice, NodeStructure/Slot-Konfiguration (Patch-Panel-Modellierung) und NetworkSchemaSettings (welche Netzknotentypen im Netzschema ausgeblendet werden) - diese sind (noch) nicht Teil des Handbuch-Umfangs bzw. hatten keinen passenden API-Endpunkt zum Export.</p><h2 id="daten-aktualisieren" tabindex="-1">Daten aktualisieren <a class="header-anchor" href="#daten-aktualisieren" aria-label="Permalink to &quot;Daten aktualisieren&quot;">​</a></h2><p>Der Export wurde per Browser-Skript (JavaScript, gegen die eingeloggte Session auf app.geodock.de) erzeugt, da es keinen fertigen &quot;Alles exportieren&quot;-Knopf in der App gibt. Kurzfassung, falls die Daten irgendwann neu gezogen werden müssen:</p><ol><li>In app.geodock.de einloggen (im Browser).</li><li>Über die Browser-Konsole/DevTools gegen <code>https://api.geodock.de/api/v1/</code> für jede benötigte Ressource (<code>trench</code>, <code>conduit</code>, <code>trench_conduit_connection</code>, <code>microduct</code>, <code>microduct_connection</code>, <code>microduct_cable_connection</code>, <code>node</code>, <code>address</code>, <code>residential-unit</code>, <code>cable</code>, <code>cable_label</code>, <code>fiber</code>, <code>area</code> jeweils mit <code>?project=&lt;id&gt;</code>, sowie die globalen <code>attributes_*</code>- und <code>flags</code>-Listen ohne Projektfilter) alle Seiten abrufen und zu einem JSON-Objekt zusammenführen. Achtung: <code>trench</code>, <code>node</code>, <code>address</code> und <code>area</code> liefern pro Seite eine GeoJSON-<code>FeatureCollection</code> (<code>results.features</code>), alle anderen Ressourcen ein einfaches <code>results</code>-Array - siehe <code>import_geodock_export.py</code> für die genaue Verarbeitungslogik.</li><li>Als JSON-Datei speichern und mit <code>import_geodock_export.py --file ... --force</code> in die lokale Instanz einspielen.</li></ol><h2 id="import-command" tabindex="-1">Import-Command <a class="header-anchor" href="#import-command" aria-label="Permalink to &quot;Import-Command&quot;">​</a></h2><p><code>import_geodock_export.py</code> wird von <code>setup-local-qonnectra.sh</code> nach <code>local-app/backend/apps/api/management/commands/</code> kopiert (lokal-app/ ist gitignored und wird bei jedem Lauf neu aus dem Checkout ergänzt). Danach:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import_geodock_export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /pfad/zur/datei.json</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--force]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Ohne <code>--force</code> wird ein bereits vorhandenes lokales Projekt &quot;Testprojekt&quot; übersprungen (kein erneuter Import). Mit <code>--force</code> wird es vorher komplett gelöscht und neu importiert.</p>',10)])])}const k=o(i,[["render",d]]);export{u as __pageData,k as default};
